  stream: false,
  format: $json.caseSchema,
  messages: [
    {
      role: "user",
      content: $json.message + "\n\nYou are a senior software QA analyst. Analyze the supplied application screenshots and generate comprehensive, actionable test cases based only on available evidence. Write exactly one test case for each scenario listed under SCENARIOS at the end of this message, in the same order, using the scenario as the test case title. Do not add, skip or merge scenarios. Include positive, negative, validation, and usability scenarios where supported. Do not invent unsupported functionality. Avoid duplicates. Use OVERALL expected results only. Do not include stepExpectedResults. Every field must be populated. Return only valid JSON using this structure: {\"testCases\":[{\"title\":\"Test case title\",\"description\":\"What this test validates\",\"precondition\":\"Required starting condition\",\"steps\":[\"Step 1\",\"Step 2\"],\"data\":\"Test data\",\"expectedResult\":\"Comprehensive expected behavior\"}]}" + "\n\nSCENARIOS:\n" + $json.scenarioList,
      images: $json.ollamaImages ?? []
    }

  ],
  options: {
    temperature: 0.2,
    num_predict: $json.numPredict,
    num_ctx: $json.numCtx
  }
})
}}

