const items = $input.all();

if (items.length === 0) {
  throw new Error("No generation context received");
}

const item = items[0];
const evidenceFiles = item.json.evidenceFiles ?? [];
const images = [];

for (const file of evidenceFiles) {
  const binaryProperty = file.binaryProperty;

  if (!item.binary?.[binaryProperty]) {
    throw new Error(`Missing evidence binary: ${binaryProperty}`);
  }

  const buffer = await this.helpers.getBinaryDataBuffer(
    0,
    binaryProperty
  );

  images.push(buffer.toString("base64"));
}

return [
  {
    json: {
      ...item.json,
      ollamaImages: images,
      ollamaImageCount: images.length,
    },
    binary: item.binary,
  },
];

