  messages: [
    {
      role: "user",
      content: $json.message + "\n\nYou are a senior software QA analyst. List the distinct test scenarios needed to cover what is actually shown in the screenshots or described in the request above, one short title (under 15 words) each. Cover every element and rule at least once, including negative and edge cases only where the evidence supports them. Only add a scenario if it checks something no other scenario checks. Stop as soon as everything shown is covered; do not invent features. If the request asks for a specific number of test cases, list exactly that many scenarios. Return only JSON: {\"scenarios\":[\"Scenario title\"]}",
      images: $json.ollamaImages ?? []
    }
  ],
  options: {
    temperature: 0.2,
    repeat_penalty: 1.15,
    repeat_last_n: -1,
    num_predict: 1200,
    num_ctx: Math.min(16384, 6144 + 1536 * ($json.ollamaImageCount || 0))
  }
})
}}

parameters.jsCode:
const context = $("Prepare Ollama Images").first().json;
const rawText = $input.first().json.message?.content ?? "";
const generationFormat =
  context.generationFormat === "PER_STEP" ? "PER_STEP" : "OVERALL";

const cleaned = String(rawText)
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/, "")
  .trim();

let listed = [];
try {
  const parsed = JSON.parse(cleaned);
  listed = Array.isArray(parsed?.scenarios) ? parsed.scenarios : [];
} catch {
  // Cut-off answer: keep every complete quoted title after "scenarios".
  const start = cleaned.indexOf("[");
  if (start !== -1) {
    for (const m of cleaned.slice(start).matchAll(/"((?:[^"\\]|\\.)*)"/g)) {
      try { listed.push(JSON.parse('"' + m[1] + '"')); } catch {}
    }
  }
}

// Small models repeat themselves; drop titles that say the same thing.
const STOP = new Set(["verify","test","check","ensure","validate","that","the","a","an","is","are","of","to","with","when","and","or","on","in","for","be","user","can"]);
function words(title) {
  return new Set(
    title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").split(" ")
      .filter((x) => x && !STOP.has(x))
  );
}
function similar(a, b) {
  if (a.size === 0 || b.size === 0) return false;
  let shared = 0;
  for (const x of a) if (b.has(x)) shared += 1;
  return shared / Math.min(a.size, b.size) >= 0.85 && shared / Math.max(a.size, b.size) >= 0.6;
}

const scenarios = [];
const seen = [];
for (const item of listed) {
  const title = typeof item === "string" ? item.replace(/\s+/g, " ").trim().slice(0, 300) : "";
  if (!title) continue;
  const key = words(title);
  if (seen.some((other) => similar(key, other))) continue;
  seen.push(key);
  scenarios.push(title);
}

// An explicit count in the request wins ("5 test cases", "exactly 3 tests").
const asked = /\b(\d{1,3})\s+(?:test[\s-]*cases?|tests?|cases?|scenarios?)\b/i.exec(context.message);
const requested = asked ? Math.min(100, Math.max(1, Number(asked[1]))) : null;

let planned = scenarios;
if (requested) {
  planned = scenarios.slice(0, requested);
  for (let i = planned.length; i < requested; i += 1) {
    planned.push("Another distinct scenario supported by the evidence (choose your own title)");
  }
}

if (planned.length === 0) {
  throw new Error("The model did not list any test scenarios for this evidence");
}

const caseCount = planned.length;
const steps = { type: "array", items: { type: "string" }, minItems: 1, maxItems: 15 };
const properties = {
  title: { type: "string" },
  description: { type: "string" },
  precondition: { type: "string" },
  steps,
};
if (generationFormat === "PER_STEP") {
  properties.stepExpectedResults = steps;
}
properties.data = { type: "string" };
properties.expectedResult = { type: "string" };

const caseSchema = {
  type: "object",
  properties: {
    testCases: {
      type: "array",
      minItems: caseCount,
      maxItems: caseCount,
      items: { type: "object", properties, required: Object.keys(properties) },
    },
  },
  required: ["testCases"],
};

const perCase = generationFormat === "PER_STEP" ? 600 : 420;
const numPredict = caseCount * perCase + 500;
const promptTokens = 1500 + Math.ceil(String(context.message).length / 3) + caseCount * 25;
const imageTokens = 1536 * (context.ollamaImageCount || 0);
const numCtx = Math.min(32768, Math.max(8192, Math.ceil((promptTokens + imageTokens + numPredict) / 1024) * 1024));

return [
  {
    json: {
      ...context,
      scenarios: planned,
      scenarioList: planned.map((title, i) => (i + 1) + ". " + title).join("\n"),
      caseCount,
      requestedCount: requested,
      caseSchema,
      numPredict,
      numCtx,
    },
  },
];
